//! The words of a language: lemmas by how often they are met, the forms each
//! one takes, and how it sounds.
//!
//! A lexicon is reference data about a language, not material for a learner,
//! which is why it is built into the binary rather than loaded like a pack:
//! the version of hilvan is the version of its lexicon, and there is no
//! second copy in the database to drift from it. `lexicons/en/lexicon.tsv` is
//! generated by `tools/lexicon/build.py` from wordfreq, the English Speller
//! Database, UD English-EWT and `CMUdict` - see `lexicons/en/README.md` for the
//! sources and their licence.
//!
//! Beside it, `lexicons/en/reading.toml` says what reading a text needs and a
//! list of lemmas cannot say: that *don't* is two words, and that the full
//! stop of *Mr.* ends no sentence. Rules of the written language, kept as
//! data so the code knows no English.
//!
//! And `lexicons/en/families.tsv` says which lemmas are made from one
//! another - *decide*, *decision*, *decisive* - generated by
//! `tools/lexicon/families.py` from the Open English `WordNet`. A family is
//! shown with a word; it changes nothing about how a text is read, so it is
//! not part of the reading's [`fingerprint`].

use std::collections::{HashMap, HashSet};
use std::sync::LazyLock;

use serde::{Deserialize, Serialize};

/// The levels a learner aims at: the commonest thousand lemmas, two
/// thousand, five thousand. Cumulative - knowing the 2k level means knowing
/// the first two thousand, not the second - because that is how a learner
/// says it ("I know two thousand words"). A product decision, the same for
/// every language.
pub const LEVELS: [u32; 3] = [1000, 2000, 5000];

/// One lemma of the lexicon.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    /// 1 for the commonest lemma of the language.
    pub rank: u32,
    /// As it is written: "go", "I", "Monday".
    pub lemma: String,
    /// The transcription, IPA; `None` when the source has none.
    pub ipa: Option<String>,
    /// Every other spelling it takes, lowercase: "went", "gone", "goes".
    pub forms: Vec<String>,
}

impl Entry {
    /// The smallest level that holds this lemma, or `None` past the last.
    #[must_use]
    pub fn level(&self) -> Option<u32> {
        level(self.rank)
    }
}

/// The smallest level a rank falls in.
#[must_use]
pub fn level(rank: u32) -> Option<u32> {
    LEVELS.into_iter().find(|level| rank <= *level)
}

/// A language's lemmas, with the lookups the tutor needs.
#[derive(Debug)]
pub struct Lexicon {
    entries: Vec<Entry>,
    /// Lowercase lemma -> its entry.
    by_lemma: HashMap<String, usize>,
    /// Lowercase spelling -> every entry it is a spelling of: "left" is
    /// "leave" and "left".
    by_form: HashMap<String, Vec<usize>>,
    writing: Writing,
    /// Each family, its members as indices into `entries`, commonest first.
    families: Vec<Vec<usize>>,
    /// Entry -> the family it is in, as an index into `families`.
    family_of: HashMap<usize, usize>,
}

/// How a language is written, as far as reading a text needs: the rules in
/// `lexicons/<language>/reading.toml`.
#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Writing {
    /// Endings that are a word of their own - "n't" is "not" - each with the
    /// lemmas it can be; an empty list adds no word.
    #[serde(default)]
    clitics: HashMap<String, Vec<String>>,
    /// Spellings of several words the endings cannot split: "can't".
    #[serde(default)]
    whole: HashMap<String, Vec<Vec<String>>>,
    /// Words written with a full stop that ends no sentence, lowercase,
    /// without the stop.
    #[serde(default)]
    abbreviations: HashSet<String>,
}

/// A rules file that cannot be read.
#[derive(Debug, thiserror::Error)]
#[error("the reading rules are not valid: {0}")]
pub struct BadWriting(#[from] toml::de::Error);

impl Writing {
    /// Reads a rules file.
    ///
    /// # Errors
    ///
    /// Fails on TOML that does not parse or has a key the rules do not have.
    pub fn parse(text: &str) -> Result<Self, BadWriting> {
        Ok(toml::from_str(text)?)
    }

    /// The endings, longest first, so a longer ending is never read as a
    /// shorter one.
    fn endings(&self) -> Vec<(&str, &[String])> {
        let mut endings: Vec<(&str, &[String])> = self.clitics.iter().map(|(ending, lemmas)| (ending.as_str(), lemmas.as_slice())).collect();
        endings.sort_by(|a, b| b.0.chars().count().cmp(&a.0.chars().count()).then_with(|| a.0.cmp(b.0)));
        endings
    }

    /// Every lemma the rules name, for the test that holds them to the
    /// lexicon.
    #[cfg(test)]
    fn named(&self) -> impl Iterator<Item = &str> {
        self.clitics
            .values()
            .flatten()
            .chain(self.whole.values().flatten().flatten())
            .map(String::as_str)
    }
}

/// A line of a families file that cannot be read, or a family the lexicon
/// does not hold.
#[derive(Debug, thiserror::Error)]
pub enum BadFamily {
    #[error("line {line} of the families is not `head<TAB>members`: {text:?}")]
    Malformed { line: usize, text: String },
    #[error("line {line} of the families names {lemma:?}, which is not a lemma of the lexicon as it is written there")]
    NotALemma { line: usize, lemma: String },
    #[error("line {line} of the families puts {lemma:?} in a second family")]
    Twice { line: usize, lemma: String },
    #[error("line {line} of the families is a family of one")]
    Alone { line: usize },
}

/// A line of a lexicon file that cannot be read.
#[derive(Debug, thiserror::Error)]
#[error("line {line} of the lexicon is not `rank<TAB>lemma<TAB>ipa<TAB>forms`: {text:?}")]
pub struct Malformed {
    line: usize,
    text: String,
}

impl Lexicon {
    /// Reads a lexicon file: `#` comments, then one lemma a line.
    ///
    /// # Errors
    ///
    /// Fails on a line without four tab-separated fields or with a rank that
    /// is not a number - a lexicon with a hole in it would rank words wrong
    /// without saying so.
    pub fn parse(text: &str) -> Result<Self, Malformed> {
        let mut entries = Vec::new();
        for (index, line) in text.lines().enumerate() {
            let line = line.trim_end_matches('\r');
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let malformed = || Malformed {
                line: index + 1,
                text: line.to_string(),
            };
            let mut fields = line.split('\t');
            let (Some(rank), Some(lemma), Some(ipa), Some(forms), None) = (fields.next(), fields.next(), fields.next(), fields.next(), fields.next()) else {
                return Err(malformed());
            };
            let rank = rank.parse().map_err(|_| malformed())?;
            if lemma.is_empty() {
                return Err(malformed());
            }
            entries.push(Entry {
                rank,
                lemma: lemma.to_string(),
                ipa: (!ipa.is_empty()).then(|| ipa.to_string()),
                forms: forms.split(' ').filter(|form| !form.is_empty()).map(str::to_string).collect(),
            });
        }

        let mut by_lemma = HashMap::with_capacity(entries.len());
        let mut by_form: HashMap<String, Vec<usize>> = HashMap::with_capacity(entries.len() * 2);
        for (index, entry) in entries.iter().enumerate() {
            let key = entry.lemma.to_lowercase();
            by_form.entry(key.clone()).or_default().push(index);
            by_lemma.entry(key).or_insert(index);
            for form in &entry.forms {
                by_form.entry(form.clone()).or_default().push(index);
            }
        }
        Ok(Self {
            entries,
            by_lemma,
            by_form,
            writing: Writing::default(),
            families: Vec::new(),
            family_of: HashMap::new(),
        })
    }

    /// The same lexicon, read with these rules of writing.
    #[must_use]
    pub fn with_writing(self, writing: Writing) -> Self {
        Self { writing, ..self }
    }

    /// The same lexicon, with its word families: `#` comments, then one
    /// family a line - its head, a tab, the other members space-separated.
    ///
    /// # Errors
    ///
    /// Fails on a line that is not two tab-separated fields, a member that is
    /// not a lemma as the lexicon writes it, a lemma in two families, and a
    /// family of one: a family is shown with a word, and a wrong one is a
    /// wrong thing taught.
    pub fn with_families(mut self, text: &str) -> Result<Self, BadFamily> {
        let mut families = Vec::new();
        let mut family_of = HashMap::new();
        for (index, line) in text.lines().enumerate() {
            let line = line.trim_end_matches('\r');
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let number = index + 1;
            let Some((head, rest)) = line.split_once('\t') else {
                return Err(BadFamily::Malformed {
                    line: number,
                    text: line.to_string(),
                });
            };
            let mut members = Vec::new();
            for lemma in std::iter::once(head).chain(rest.split(' ').filter(|lemma| !lemma.is_empty())) {
                let Some(&entry) = self.by_lemma.get(&lemma.to_lowercase()).filter(|&&entry| self.entries[entry].lemma == lemma) else {
                    return Err(BadFamily::NotALemma {
                        line: number,
                        lemma: lemma.to_string(),
                    });
                };
                if family_of.insert(entry, families.len()).is_some() {
                    return Err(BadFamily::Twice {
                        line: number,
                        lemma: lemma.to_string(),
                    });
                }
                members.push(entry);
            }
            if members.len() < 2 {
                return Err(BadFamily::Alone { line: number });
            }
            members.sort_by_key(|&entry| self.entries[entry].rank);
            families.push(members);
        }
        self.families = families;
        self.family_of = family_of;
        Ok(self)
    }

    /// The family a lemma is in, commonest first and the lemma among them;
    /// empty for a lemma made from no other and no other from it.
    #[must_use]
    pub fn family(&self, lemma: &str) -> Vec<&Entry> {
        self.by_lemma
            .get(&lemma.to_lowercase())
            .and_then(|entry| self.family_of.get(entry))
            .map(|&family| self.families[family].iter().map(|&entry| &self.entries[entry]).collect())
            .unwrap_or_default()
    }

    /// The words a running word of a text is made of, each the lemmas it can
    /// be: "went" is `[["go"]]`, "left" `[["leave", "left"]]`, "don't"
    /// `[["do"], ["not"]]`, "well-known" `[["well"], ["know"]]`. Empty for a
    /// spelling the lexicon cannot read.
    ///
    /// A spelling the lexicon has is taken whole before it is split: "o'clock"
    /// is a word, and so is "cannot".
    #[must_use]
    pub fn parts(&self, written: &str) -> Vec<Vec<&str>> {
        let spelling = written.to_lowercase().replace('\u{2019}', "'");
        self.parts_of(&spelling).unwrap_or_default()
    }

    fn parts_of(&self, spelling: &str) -> Option<Vec<Vec<&str>>> {
        let lemmas = self.lemmas_of(spelling);
        if !lemmas.is_empty() {
            return Some(vec![lemmas]);
        }
        // The lemmas a rule names, as the lexicon writes them - "I", not "i".
        let named = |lemmas: &[String]| -> Vec<&str> { lemmas.iter().filter_map(|lemma| self.entry(lemma).map(|entry| entry.lemma.as_str())).collect() };
        if let Some(words) = self.writing.whole.get(spelling) {
            let parts: Vec<Vec<&str>> = words.iter().map(|lemmas| named(lemmas)).collect();
            return parts.iter().all(|part| !part.is_empty()).then_some(parts);
        }
        for (ending, lemmas) in self.writing.endings() {
            let Some(stem) = spelling.strip_suffix(ending).filter(|stem| !stem.is_empty()) else {
                continue;
            };
            let stem = self.lemmas_of(stem);
            if stem.is_empty() {
                continue;
            }
            let mut parts = vec![stem];
            let ending = named(lemmas);
            if !ending.is_empty() {
                parts.push(ending);
            }
            return Some(parts);
        }
        if spelling.contains('-') {
            let mut parts = Vec::new();
            for piece in spelling.split('-').filter(|piece| !piece.is_empty()) {
                parts.extend(self.parts_of(piece)?);
            }
            return (!parts.is_empty()).then_some(parts);
        }
        None
    }

    /// Whether a word written with a full stop - lowercase, the stop left
    /// off - is an abbreviation rather than the end of a sentence.
    #[must_use]
    pub fn is_abbreviation(&self, word: &str) -> bool {
        self.writing.abbreviations.contains(word)
    }

    /// The lemma, whatever case it is asked in.
    #[must_use]
    pub fn entry(&self, lemma: &str) -> Option<&Entry> {
        self.by_lemma.get(&lemma.to_lowercase()).map(|&index| &self.entries[index])
    }

    /// Whether `spelling` is the lemma itself or one of its forms.
    #[must_use]
    pub fn is_spelling_of(&self, spelling: &str, lemma: &str) -> bool {
        let lemma = lemma.to_lowercase();
        self.by_form
            .get(&spelling.to_lowercase())
            .is_some_and(|entries| entries.iter().any(|&index| self.entries[index].lemma.to_lowercase() == lemma))
    }

    /// Every lemma a spelling can be: "left" is "leave" and "left". Empty for
    /// a spelling the lexicon has never met.
    #[must_use]
    pub fn lemmas_of(&self, spelling: &str) -> Vec<&str> {
        self.by_form
            .get(&spelling.to_lowercase())
            .map(|entries| entries.iter().map(|&index| self.entries[index].lemma.as_str()).collect())
            .unwrap_or_default()
    }

    /// How many lemmas it holds.
    #[must_use]
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Whether it holds none.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Every lemma, commonest first.
    pub fn entries(&self) -> impl Iterator<Item = &Entry> {
        self.entries.iter()
    }
}

const ENGLISH_LEXICON: &str = include_str!("../lexicons/en/lexicon.tsv");
const ENGLISH_WRITING: &str = include_str!("../lexicons/en/reading.toml");
const ENGLISH_FAMILIES: &str = include_str!("../lexicons/en/families.tsv");

static ENGLISH: LazyLock<Lexicon> = LazyLock::new(|| {
    // Built into the binary and parsed by a test on every gate run, so a
    // malformed file never reaches a stand: this cannot fail at runtime
    // without failing the build first.
    let lexicon = Lexicon::parse(ENGLISH_LEXICON).unwrap_or_else(|error| panic!("the English lexicon is malformed: {error}"));
    let writing = Writing::parse(ENGLISH_WRITING).unwrap_or_else(|error| panic!("the English reading rules are malformed: {error}"));
    lexicon
        .with_writing(writing)
        .with_families(ENGLISH_FAMILIES)
        .unwrap_or_else(|error| panic!("the English word families are malformed: {error}"))
});

/// What a text of a language is read with, as one short string: the
/// SHA-256 of its lexicon and its rules of writing. Whatever was counted of
/// a text with another fingerprint was counted with another reading.
#[must_use]
pub fn fingerprint(language: &str) -> Option<String> {
    use std::fmt::Write as _;

    use sha2::{Digest, Sha256};
    let (lexicon, writing) = match language {
        "en" => (ENGLISH_LEXICON, ENGLISH_WRITING),
        _ => return None,
    };
    let mut hash = Sha256::new();
    hash.update(lexicon.as_bytes());
    hash.update([0]);
    hash.update(writing.as_bytes());
    Some(hash.finalize().iter().take(12).fold(String::new(), |mut hex, byte| {
        let _ = write!(hex, "{byte:02x}");
        hex
    }))
}

/// The lexicon of a language, when hilvan has one.
#[must_use]
pub fn of(language: &str) -> Option<&'static Lexicon> {
    match language {
        "en" => Some(&ENGLISH),
        _ => None,
    }
}

/// A word of a sentence, as it stands in it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct Token<'a> {
    /// As written: "Went", "doctor's".
    pub text: &'a str,
    /// Where it starts, counted in characters - what the app highlights by.
    pub start: usize,
}

impl Token<'_> {
    /// The spelling a lexicon is asked about: lowercase, a curly apostrophe
    /// made straight, and a possessive taken off - "doctor's" is "doctor".
    #[must_use]
    pub fn spelling(&self) -> String {
        let lower = self.text.to_lowercase().replace('\u{2019}', "'");
        lower.strip_suffix("'s").map_or_else(|| lower.clone(), str::to_string)
    }
}

/// The words of a sentence: letters, joined by an apostrophe or a hyphen
/// inside a word ("don't", "well-known"), everything else a separator.
#[must_use]
pub fn tokens(text: &str) -> Vec<Token<'_>> {
    let mut tokens = Vec::new();
    let mut start: Option<(usize, usize)> = None;
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    for (position, &(byte, ch)) in chars.iter().enumerate() {
        let joins = matches!(ch, '\'' | '\u{2019}' | '-') && start.is_some() && chars.get(position + 1).is_some_and(|(_, next)| next.is_alphabetic());
        if ch.is_alphabetic() || joins {
            start.get_or_insert((byte, position));
        } else if let Some((from, at)) = start.take() {
            tokens.push(Token {
                text: &text[from..byte],
                start: at,
            });
        }
    }
    if let Some((from, at)) = start {
        tokens.push(Token {
            text: &text[from..],
            start: at,
        });
    }
    tokens
}

/// Where a lemma stands in a sentence: the first word that is the lemma or
/// one of its forms.
///
/// Without a lexicon for the language, only the lemma's own spelling is
/// found: a guess at another language's morphology would be a wrong answer
/// given with confidence.
#[must_use]
pub fn find<'a>(lexicon: Option<&Lexicon>, sentence: &'a str, lemma: &str) -> Option<Token<'a>> {
    let wanted = lemma.to_lowercase();
    tokens(sentence).into_iter().find(|token| {
        let spelling = token.spelling();
        spelling == wanted || lexicon.is_some_and(|lexicon| lexicon.is_spelling_of(&spelling, lemma))
    })
}

/// How many other words may stand between two words of a phrase: *turn
/// the kitchen light off* is still *turn off*, and *made a quick decision*
/// still *make a decision*.
pub const PHRASE_GAP: usize = 3;

/// Where a word or a phrase stands in a sentence.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Found<'a> {
    /// From the first of its words to the last, as written: "turned the
    /// light off" for *turn off*.
    pub text: &'a str,
    /// Where that stretch starts, counted in characters.
    pub start: usize,
    /// Its own words, as they stand: "turned" and "off". One for a word.
    pub parts: Vec<Token<'a>>,
}

/// Where a word of one or several words stands in a sentence: each of them
/// as itself or one of its forms, in order, with at most [`PHRASE_GAP`]
/// other words between two of them. The first place it is found.
///
/// A phrase is a word of several - *make a decision*, *turn off* - and the
/// deck learns it as one: it is found the way each of its words would be.
#[must_use]
pub fn locate<'a>(lexicon: Option<&Lexicon>, sentence: &'a str, word: &str) -> Option<Found<'a>> {
    let wanted: Vec<&str> = word.split_whitespace().collect();
    let tokens = tokens(sentence);
    let is = |token: &Token<'_>, lemma: &str| {
        let spelling = token.spelling();
        spelling == lemma.to_lowercase() || lexicon.is_some_and(|lexicon| lexicon.is_spelling_of(&spelling, lemma))
    };
    let (first, rest) = wanted.split_first()?;
    'start: for (at, token) in tokens.iter().enumerate() {
        if !is(token, first) {
            continue;
        }
        let mut parts = vec![*token];
        let mut from = at + 1;
        for lemma in rest {
            let window = tokens.iter().enumerate().skip(from).take(PHRASE_GAP + 1);
            let Some((next, token)) = window.into_iter().find(|(_, token)| is(token, lemma)) else {
                continue 'start;
            };
            parts.push(*token);
            from = next + 1;
        }
        let last = parts.last().copied().unwrap_or(*token);
        let begin = sentence.char_indices().nth(token.start).map_or(sentence.len(), |(byte, _)| byte);
        let end = sentence.char_indices().nth(last.start).map_or(sentence.len(), |(byte, _)| byte) + last.text.len();
        return Some(Found {
            text: &sentence[begin..end],
            start: token.start,
            parts,
        });
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_phrase_is_found_by_its_words_in_order_with_a_few_between() {
        let lexicon = Lexicon::parse("1\tturn\t\tturned turning turns\n2\toff\t\t\n3\tmake\t\tmade makes\n4\ta\t\t\n5\tdecision\t\tdecisions\n").unwrap();
        let found = locate(Some(&lexicon), "She turned the light off.", "turn off").expect("turned ... off");
        assert_eq!((found.text, found.start), ("turned the light off", 4));
        assert_eq!(found.parts.iter().map(|part| part.text).collect::<Vec<_>>(), ["turned", "off"]);
        assert_eq!(
            locate(Some(&lexicon), "We made a quick decision.", "make a decision").map(|found| found.text),
            Some("made a quick decision")
        );
        assert!(
            locate(Some(&lexicon), "Turn the old kitchen light off.", "turn off").is_none(),
            "four words apart is two words, not a phrase"
        );
        assert!(locate(Some(&lexicon), "Off we turned.", "turn off").is_none(), "in its order or not at all");
        assert_eq!(
            locate(Some(&lexicon), "Turn left, then turn it off.", "turn off").map(|found| found.start),
            Some(16),
            "a first word that leads nowhere is passed over"
        );
        let word = locate(Some(&lexicon), "Decisions, decisions.", "decision").expect("one word is a phrase of one");
        assert_eq!((word.text, word.start, word.parts.len()), ("Decisions", 0, 1));
    }

    const SMALL: &str = "# a comment\n1\tgo\tɡoʊ\tgoes going gone went\n2\tleave\tliv\tleaves leaving left\n3\tleft\tlɛft\t\n4\tI\taɪ\t\n";

    #[test]
    fn the_shipped_lexicon_reads_whole() {
        // The gate on the file the binary carries: a malformed line here
        // would be a panic on the stand.
        let english = of("en").expect("hilvan ships an English lexicon");
        assert!(
            english.len() >= 10_000,
            "the lexicon should reach well past the 5k level, holds {}",
            english.len()
        );
        let ranks: Vec<u32> = english.entries().map(|entry| entry.rank).collect();
        assert!(ranks.windows(2).all(|pair| pair[1] == pair[0] + 1), "ranks should run 1, 2, 3 without a gap");
        assert_eq!(ranks.first(), Some(&1));
    }

    #[test]
    fn the_shipped_lexicon_knows_the_common_words_and_their_forms() {
        let english = of("en").unwrap();
        let go = english.entry("go").expect("go");
        assert!(go.rank < 100, "go is among the commonest verbs, ranked {}", go.rank);
        assert!(english.is_spelling_of("went", "go"));
        assert!(english.is_spelling_of("children", "child"));
        assert!(english.is_spelling_of("is", "be"));
        assert_eq!(
            english.entry("i").map(|entry| entry.lemma.as_str()),
            Some("I"),
            "the pronoun is written in capitals"
        );
        assert!(english.entry("Monday").is_some(), "a day is a word, capital or not");
        // "john" is a word too, a rare one: what must not happen is the name
        // carrying it into the levels a learner aims at.
        for name in ["john", "china"] {
            assert!(
                english.entry(name).is_none_or(|entry| entry.level().is_none()),
                "{name} climbed into the levels on the strength of a name"
            );
        }
        assert!(
            english
                .entry("doctor")
                .and_then(|entry| entry.ipa.as_deref())
                .is_some_and(|ipa| ipa.contains('ˈ'))
        );
    }

    #[test]
    fn the_shipped_reading_rules_name_only_lemmas_the_lexicon_has() {
        let english = of("en").unwrap();
        for lemma in english.writing.named() {
            assert!(english.entry(lemma).is_some(), "reading.toml names {lemma:?}, which the lexicon does not have");
        }
        assert!(english.is_abbreviation("mr"));
    }

    #[test]
    fn a_running_word_is_read_into_the_words_it_is_made_of() {
        let english = of("en").unwrap();
        assert_eq!(english.parts("Went"), vec![vec!["go"]]);
        assert_eq!(
            english.parts("don\u{2019}t"),
            vec![vec!["do"], vec!["not"]],
            "a curly apostrophe is an apostrophe"
        );
        assert_eq!(
            english.parts("can't"),
            vec![vec!["can"], vec!["not"]],
            "a stem that is no word is spelled out whole"
        );
        assert_eq!(english.parts("I'm"), vec![vec!["I"], vec!["be"]], "lemmas as the lexicon writes them");
        assert_eq!(english.parts("doctor's"), vec![vec!["doctor"]], "the 's adds no word");
        assert_eq!(english.parts("cannot"), vec![vec!["cannot"]], "a spelling the lexicon has is taken whole");
        let known = english.parts("well-known");
        assert_eq!(known.len(), 2, "{known:?}");
        assert!(known[0] == vec!["well"] && known[1].contains(&"know"), "{known:?}");
        assert_eq!(english.parts("zxqv"), Vec::<Vec<&str>>::new());
        assert!(english.parts("well-zxqv").is_empty(), "a hyphenated word is read whole or not at all");
        let left = english.parts("left");
        assert_eq!(left.len(), 1);
        assert!(left[0].contains(&"leave") && left[0].contains(&"left"), "{left:?}");
        let would = english.parts("you'd");
        assert_eq!(would[0], vec!["you"]);
        assert!(would[1].contains(&"will") && would[1].contains(&"have"), "'d is would or had: {would:?}");
    }

    #[test]
    fn without_rules_a_running_word_is_only_its_spelling() {
        let lexicon = Lexicon::parse(SMALL).unwrap();
        assert_eq!(lexicon.parts("went"), vec![vec!["go"]]);
        assert!(lexicon.parts("goes'll").is_empty(), "no endings without the rules that name them");
        let ruled = Lexicon::parse(SMALL)
            .unwrap()
            .with_writing(Writing::parse("[clitics]\n\"'ll\" = [\"go\"]\n").unwrap());
        assert_eq!(ruled.parts("goes'll"), vec![vec!["go"], vec!["go"]]);
        assert!(Writing::parse("[unknown]\n").is_err(), "a key the rules do not have");
    }

    #[test]
    fn a_rank_falls_in_the_smallest_level_that_holds_it() {
        assert_eq!(level(1), Some(1000));
        assert_eq!(level(1000), Some(1000));
        assert_eq!(level(1001), Some(2000));
        assert_eq!(level(4999), Some(5000));
        assert_eq!(level(5001), None);
    }

    #[test]
    fn a_spelling_can_belong_to_two_lemmas() {
        let lexicon = Lexicon::parse(SMALL).unwrap();
        assert!(lexicon.is_spelling_of("left", "leave"));
        assert!(lexicon.is_spelling_of("left", "left"));
        assert!(lexicon.is_spelling_of("Went", "GO"), "case is not a different word");
        assert!(!lexicon.is_spelling_of("went", "leave"));
    }

    #[test]
    fn a_malformed_line_is_refused_with_its_number() {
        let error = Lexicon::parse("1\tgo\tɡoʊ\tgoes\nnot-a-rank\tbe\tbi\t\n").unwrap_err();
        assert!(error.to_string().contains("line 2"), "{error}");
        assert!(Lexicon::parse("1\tgo\n").is_err(), "a line with fields missing");
    }

    #[test]
    fn the_shipped_families_hold_words_made_from_one_another() {
        let english = of("en").unwrap();
        let decide: Vec<&str> = english.family("decide").iter().map(|entry| entry.lemma.as_str()).collect();
        assert!(
            decide.contains(&"decide") && decide.contains(&"decision"),
            "decide and decision are one family: {decide:?}"
        );
        let happy: Vec<&str> = english.family("Happiness").iter().map(|entry| entry.lemma.as_str()).collect();
        assert_eq!(
            happy.first(),
            Some(&"happy"),
            "the commonest member heads the family, asked in any case: {happy:?}"
        );
        assert!(happy.contains(&"happily"), "{happy:?}");
        assert!(english.family("go").is_empty(), "go is made from nothing, and nothing from it");
        // Linked by meaning only - urban pertains to city - is not a family a
        // learner can read off a word.
        let city: Vec<&str> = english.family("city").iter().map(|entry| entry.lemma.as_str()).collect();
        assert!(!city.contains(&"urban"), "{city:?}");
    }

    #[test]
    fn a_family_is_of_lemmas_the_lexicon_holds_each_once() {
        let small = || Lexicon::parse("1\tdecide\t\tdecided\n2\tdecision\t\t\n3\tgo\t\twent\n").unwrap();
        let family = small().with_families("# head, then the rest\ndecide\tdecision\n").unwrap();
        let members: Vec<&str> = family.family("decision").iter().map(|entry| entry.lemma.as_str()).collect();
        assert_eq!(members, ["decide", "decision"]);

        let unknown = small().with_families("decide\tdecisive\n").unwrap_err();
        assert!(matches!(unknown, BadFamily::NotALemma { line: 1, .. }), "{unknown}");
        let form = small().with_families("decide\tdecided\n").unwrap_err();
        assert!(matches!(form, BadFamily::NotALemma { .. }), "a form is not a member: {form}");
        let twice = small().with_families("decide\tdecision\ngo\tdecision\n").unwrap_err();
        assert!(matches!(twice, BadFamily::Twice { line: 2, .. }), "{twice}");
        let alone = small().with_families("go\t\n").unwrap_err();
        assert!(matches!(alone, BadFamily::Alone { line: 1 }), "{alone}");
        assert!(matches!(small().with_families("go decide\n").unwrap_err(), BadFamily::Malformed { .. }));
    }

    #[test]
    fn a_sentence_breaks_into_words_at_their_characters() {
        let found: Vec<(&str, usize)> = tokens("He isn't at the doctor's - well-known, ¿no?")
            .iter()
            .map(|token| (token.text, token.start))
            .collect();
        assert_eq!(
            found,
            vec![
                ("He", 0),
                ("isn't", 3),
                ("at", 9),
                ("the", 12),
                ("doctor's", 16),
                ("well-known", 27),
                ("no", 40)
            ]
        );
        // Counted in characters, not bytes: the app indexes by code point.
        let russian = tokens("Он дома.");
        assert_eq!(russian[1].start, 3);
        assert_eq!(russian[1].text, "дома");
    }

    #[test]
    fn a_lemma_is_found_by_any_of_its_forms() {
        let lexicon = Lexicon::parse(SMALL).unwrap();
        let token = find(Some(&lexicon), "She went home.", "go").expect("went is a form of go");
        assert_eq!((token.text, token.start), ("went", 4));
        assert!(find(Some(&lexicon), "She stayed home.", "go").is_none());
        assert_eq!(find(Some(&lexicon), "The doctor's bag.", "doctor").map(|token| token.text), Some("doctor's"));
    }

    #[test]
    fn without_a_lexicon_only_the_lemma_itself_is_found() {
        assert!(find(None, "Ella fue a casa.", "ir").is_none(), "no guessing at Spanish verbs");
        assert_eq!(find(None, "Voy a casa.", "casa").map(|token| token.start), Some(6));
    }
}
